#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minPartitionScore(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<long long> dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            long long best = LLONG_MAX;
            long long cur_max = 0;
            for (int j = i - 1; j >= std::max(0, i - k); --j) {
                cur_max = std::max(cur_max, (long long)nums[j]);
                best = std::min(best, dp[j] + cur_max);
            }
            dp[i] = best;
        }
        return dp[n];
    }
};

import java.util.*;

class Solution {
    public int minPartitionScore(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            long best = Long.MAX_VALUE;
            long curMax = 0;
            for (int j = i - 1; j >= Math.max(0, i - k); j--) {
                curMax = Math.max(curMax, nums[j]);
                best = Math.min(best, dp[j] + curMax);
            }
            dp[i] = best;
        }
        return (int) dp[n];
    }
}

